from itertools import islice


def _is_scalar(value):
    """Return True for strings, bytes, and non-iterable values."""
    if isinstance(value, (str, bytes)):
        return True
    try:
        iter(value)
    except TypeError:
        return True
    return False


def _flatten(obj):
    """Yield the scalar leaves of *obj* in order."""
    if _is_scalar(obj):
        yield obj
    else:
        for item in obj:
            yield from _flatten(item)


def _fill(flat, dims):
    """Build one value of shape *dims* from *flat*.

    Return None if *flat* runs out before the shape is complete.
    """
    if len(dims) == 1:
        items = tuple(islice(flat, dims[0]))
        return items if len(items) == dims[0] else None
    parts = []
    for _ in range(dims[0]):
        part = _fill(flat, dims[1:])
        if part is None:
            return None
        parts.append(part)
    return tuple(parts)


def _reshape_columns(rows, cols):
    """Yield complete rows of length *cols* from the scalars in *rows*."""
    flat = _flatten(rows)
    while True:
        row = _fill(flat, (cols,))
        if row is None:
            return
        yield row


def _reshape_dims(matrix, dims):
    """Yield the outermost elements of a tensor of shape *dims*."""
    flat = _flatten(matrix)
    if len(dims) == 1:
        part = _fill(flat, dims)
        if part is not None:
            yield from part
        return
    for _ in range(dims[0]):
        row = _fill(flat, dims[1:])
        if row is None:
            return
        yield row


def reshape(matrix, shape):
    """Change the shape of a *matrix*.

    If *shape* is an integer, the matrix must be two dimensional
    and the shape is interpreted as the desired number of columns:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]
        >>> cols = 3
        >>> list(reshape(matrix, cols))
        [(0, 1, 2), (3, 4, 5)]

    If *shape* is a tuple (or other iterable), the input matrix can have
    any number of dimensions. It will first be flattened and then rebuilt
    to the desired shape which can also be multidimensional:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]    # Start with a 3 x 2 matrix

        >>> list(reshape(matrix, (2, 3)))        # Make a 2 x 3 matrix
        [(0, 1, 2), (3, 4, 5)]

        >>> list(reshape(matrix, (6,)))          # Make a vector of length six
        [0, 1, 2, 3, 4, 5]

        >>> list(reshape(matrix, (2, 1, 3, 1)))  # Make 2 x 1 x 3 x 1 tensor
        [(((0,), (1,), (2,)),), (((3,), (4,), (5,)),)]

    Each dimension is assumed to be uniform, either all arrays or all scalars.
    Flattening stops when the first value in a dimension is a scalar.
    Scalars are bytes, strings, and non-iterables.
    The reshape iterator stops when the requested shape is complete
    or when the input is exhausted, whichever comes first.

    """
    if isinstance(shape, int):
        if shape < 1:
            raise ValueError("cols must be a positive integer")
        rows = list(matrix)
        for row in rows:
            if _is_scalar(row) or not all(_is_scalar(x) for x in row):
                raise ValueError("matrix must be two dimensional")
        return _reshape_columns(rows, shape)

    dims = tuple(shape)
    if not dims:
        raise ValueError("shape must not be empty")
    for dim in dims:
        if not isinstance(dim, int) or dim < 1:
            raise ValueError("every dimension must be a positive integer")
    return _reshape_dims(matrix, dims)
