from itertools import islice


def _is_scalar(item):
    """Return True for bytes, strings, and non-iterable values."""
    if isinstance(item, (bytes, str)):
        return True
    try:
        iter(item)
    except TypeError:
        return True
    return False


def _leaves(item):
    """Yield the scalar values of *item* in row-major order."""
    if _is_scalar(item):
        yield item
    else:
        for sub in item:
            yield from _leaves(sub)


def _is_count(value):
    """Return True if *value* is a non-negative integer (bool excluded)."""
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def _build(flat, shape):
    """Build a nested tuple of *shape* from *flat*, or return None if input runs out."""
    if len(shape) == 1:
        items = tuple(islice(flat, shape[0]))
        return items if len(items) == shape[0] else None
    subs = []
    for _ in range(shape[0]):
        sub = _build(flat, shape[1:])
        if sub is None:
            return None
        subs.append(sub)
    return tuple(subs)


def _rows(flat, cols):
    """Yield full rows of *cols* scalars until the input is exhausted."""
    while True:
        row = tuple(islice(flat, cols))
        if len(row) < cols:
            return
        yield row


def _reshape_shape(flat, shape):
    """Yield the outer dimension of a reshaped tuple-shaped matrix."""
    if len(shape) == 1:
        yield from islice(flat, shape[0])
        return
    for _ in range(shape[0]):
        sub = _build(flat, shape[1:])
        if sub is None:
            return
        yield sub


def reshape(matrix, shape):
    """Change the shape of a *matrix*.

    If *shape* is an integer, the matrix must be two dimensional
    and the shape is interpreted as the desired number of columns:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]
        >>> cols = 3
        >>> list(reshape(matrix, cols))
        [(0, 1, 2), (3, 4, 5)]

    If *shape* is a tuple (or other iterable), the input matrix can have
    any number of dimensions. It will first be flattened and then rebuilt
    to the desired shape which can also be multidimensional:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]    # Start with a 3 x 2 matrix

        >>> list(reshape(matrix, (2, 3)))        # Make a 2 x 3 matrix
        [(0, 1, 2), (3, 4, 5)]

        >>> list(reshape(matrix, (6,)))          # Make a vector of length six
        [0, 1, 2, 3, 4, 5]

        >>> list(reshape(matrix, (2, 1, 3, 1)))  # Make 2 x 1 x 3 x 1 tensor
        [(((0,), (1,), (2,)),), (((3,), (4,), (5,)),)]

    Each dimension is assumed to be uniform, either all arrays or all scalars.
    Flattening stops when the first value in a dimension is a scalar.
    Scalars are bytes, strings, and non-iterables.
    The reshape iterator stops when the requested shape is complete
    or when the input is exhausted, whichever comes first.

    """
    if isinstance(shape, int) and not isinstance(shape, bool):
        cols = shape
        if cols <= 0:
            raise ValueError("number of columns must be positive")
        rows = list(matrix)
        for row in rows:
            if _is_scalar(row):
                raise ValueError("matrix must be two dimensional")
            for value in row:
                if not _is_scalar(value):
                    raise ValueError("matrix must be two dimensional")
        return _rows(_leaves(rows), cols)

    shape = tuple(shape)
    if not shape:
        raise ValueError("shape must not be empty")
    for count in shape:
        if not _is_count(count):
            raise ValueError("shape entries must be non-negative integers")
    return _reshape_shape(_leaves(matrix), shape)
