from itertools import chain, islice

_MISSING = object()


def _is_scalar(obj):
    """Return True for strings, bytes and non-iterable values."""
    if isinstance(obj, (str, bytes)):
        return True
    try:
        iter(obj)
    except TypeError:
        return True
    return False


def _flatten(obj):
    """Yield all scalars of a nested, uniform structure in order."""
    if _is_scalar(obj):
        yield obj
    else:
        for item in obj:
            yield from _flatten(item)


def _chunks(iterable, size):
    """Yield tuples of *size* items; the last tuple may be shorter."""
    it = iter(iterable)
    while True:
        chunk = tuple(islice(it, size))
        if not chunk:
            return
        yield chunk


def _take(it, dims):
    """Build one object of shape *dims* from *it*.

    Return _MISSING if the iterator runs out before the object is complete.
    """
    if not dims:
        return next(it, _MISSING)
    items = []
    for _ in range(dims[0]):
        obj = _take(it, dims[1:])
        if obj is _MISSING:
            return _MISSING
        items.append(obj)
    return tuple(items)


