from itertools import islice, zip_longest


def _chunks(iterator, n):
    """Yield tuples of up to *n* items from *iterator*, the last one possibly short."""
    while True:
        chunk = tuple(islice(iterator, n))
        if not chunk:
            return
        yield chunk


def _strict_chunks(iterator, n):
    """Yield full groups of *n* items, raising ValueError on a short final group."""
    for chunk in _chunks(iterator, n):
        if len(chunk) != n:
            raise ValueError('iterable length is not a multiple of n')
        yield chunk


def _ignore_chunks(iterator, n):
    """Yield only full groups of *n* items, dropping a short final group."""
    for chunk in _chunks(iterator, n):
        if len(chunk) == n:
            yield chunk


def grouper(iterable, n, incomplete='fill', fillvalue=None):
    """Group elements from *iterable* into fixed-length groups of length *n*.

    >>> list(grouper('ABCDEF', 3))
    [('A', 'B', 'C'), ('D', 'E', 'F')]

    The keyword arguments *incomplete* and *fillvalue* control what happens for
    iterables whose length is not a multiple of *n*.

    When *incomplete* is `'fill'`, the last group will contain instances of
    *fillvalue*.

    >>> list(grouper('ABCDEFG', 3, incomplete='fill', fillvalue='x'))
    [('A', 'B', 'C'), ('D', 'E', 'F'), ('G', 'x', 'x')]

    When *incomplete* is `'ignore'`, the last group will not be emitted.

    >>> list(grouper('ABCDEFG', 3, incomplete='ignore', fillvalue='x'))
    [('A', 'B', 'C'), ('D', 'E', 'F')]

    When *incomplete* is `'strict'`, a `ValueError` will be raised.

    >>> iterator = grouper('ABCDEFG', 3, incomplete='strict')
    >>> list(iterator)  # doctest: +IGNORE_EXCEPTION_DETAIL
    Traceback (most recent call last):
    ...
    ValueError

    """
    if n < 1:
        raise ValueError('n must be at least 1')
    if incomplete not in ('fill', 'ignore', 'strict'):
        raise ValueError("incomplete must be 'fill', 'ignore' or 'strict'")
    iterator = iter(iterable)

    if incomplete == 'fill':
        return zip_longest(*[iterator] * n, fillvalue=fillvalue)
    if incomplete == 'ignore':
        return _ignore_chunks(iterator, n)
    return _strict_chunks(iterator, n)
